function CDQ_fitWidth(text,size) {
  var width=0;
  for(var i=0;i<text.length;i++)width+=CDQ_fitWidths.hasOwnProperty(text.charAt(i))?CDQ_fitWidths[text.charAt(i)]:500;
  return width*size/1000;
