  for(var i=0;i<paragraphs.length;i++){
    var words=paragraphs[i].split(" "),line="";
    for(var j=0;j<words.length;j++){
      var joined=(line+" "+words[j]).replace(/^\s+|\s+$/g,"");
      if(line&&CDQ_fitWidth(joined,size)>width){lines.push(line);line=words[j];}
