    var lines=CDQ_fitLines(value,candidate,available,spec.multiline);
    for(var i=0;i<lines.length;i++)if(CDQ_fitWidth(lines[i],candidate)>available+.000001)return false;
    return !spec.multiline||lines.length*candidate*1.19<=height+.000001;
