  if(!fits(size)){
    var low=0,high=size;
    for(var step=0;step<40;step++){var mid=(low+high)/2;if(fits(mid))low=mid;else high=mid;}
    size=Math.max(.001,Math.floor(low*1000)/1000);
  }
