function CDQ_plainProblemLabel(value) { return String(value===null||value===undefined?"":value).replace(/\u200b/g,"").replace(/[\u00a0\u202f]/g," ").replace(/\s+/g," ").replace(/^\s+|\s+$/g,""); }
function CDQ_normalizeProblems(raw) {
  // Keep the original export values, in the same order as /Opt. A malformed
  // selection containing both states must retain the unresolved defect.
  var values=raw,states={},result=[];
  if(!Array.isArray(values)){
    var text=String(values===null||values===undefined?"":values);
    if(/^\s*\[/.test(text)){try{values=JSON.parse(text);}catch(e){values=[text];}}
    else values=text.indexOf(",")>=0?text.split(","):[text];
  }
  if(!Array.isArray(values))values=[values];
  for(var i=0;i<values.length;i++){
    var choice=CDQ_plainProblemLabel(values[i]);
    if(!choice||choice==="aucun"||choice==="Aucun problème constaté")continue;
    var base=choice.replace(/_corrige$/,""),corrected=/_corrige$/.test(choice);
    if(!CDQ_labels.hasOwnProperty(base)){
      base="";
      for(var j=0;j<CDQ_problemOrder.length;j++){
        var candidate=CDQ_problemOrder[j],label=CDQ_labels[candidate];
        if(choice===label||choice===label+" (corrigé)"){base=candidate;corrected=choice!==label;break;}
      }
    }
    if(base)states[base]=states[base]===false?false:corrected;
  }
  for(var i=0;i<CDQ_problemOrder.length;i++){
    var base=CDQ_problemOrder[i];
    if(states.hasOwnProperty(base))result.push(base+(states[base]?"_corrige":""));
  }
  return result.length?result:["aucun"];
}
function CDQ_problemSelection(d,raw) {
  var menu=d.getField(CDQ_prefix+"probleme_constate");
  return CDQ_normalizeProblems(raw===undefined?(menu?menu.value:"aucun"):raw);
}
function CDQ_problemFacts(choices) {
  var unresolved=[],corrected=[];
  for(var i=0;i<choices.length;i++){
    var value=choices[i];if(value==="aucun")continue;
    var base=value.replace(/_corrige$/,"");
    (/_corrige$/.test(value)?corrected:unresolved).push(base);
  }
  return {unresolved:unresolved,corrected:corrected,count:unresolved.length+corrected.length};
}
function CDQ_problemDetail(facts) {
  var groups=[],names=[];
  for(var i=0;i<facts.unresolved.length;i++)names.push(CDQ_labels[facts.unresolved[i]]);
  if(names.length)groups.push("Non corrigé"+(names.length>1?"s":"")+" : "+names.join("; ")+".");
  names=[];
  for(var i=0;i<facts.corrected.length;i++)names.push(CDQ_labels[facts.corrected[i]]);
  if(names.length)groups.push("Corrigé"+(names.length>1?"s":"")+" : "+names.join("; ")+".");
  return groups.join(" ");
}
function CDQ_prepareMenu(d) {
  // PDF.js turns /Opt spaces into NBSP; CDQ then wraps this text anywhere.
  // Add word-boundary breaks to the live menu only. The original /Opt entries
  // stay plain WinAnsi text in the PDF, including in PDF.js saves, so CDQ's
  // Helvetica-based save normalizer can encode every selected label.
  if(app.viewerType!=="PDF.js")return;
  var menu=d.getField(CDQ_prefix+"probleme_constate");if(!menu)return;
  var selected=menu.value,items=[];
  if(menu.multipleSelection){
    // PDF.js supplies only the first selected /V item to its scripting
    // sandbox on opening. The saved JSON copy restores the complete set.
    var saved=CDQ_get(d,"dernier_probleme");
    try{var parsed=JSON.parse(saved);if(Array.isArray(parsed))selected=parsed;}catch(e){}
    selected=CDQ_normalizeProblems(selected);
  }
  for(var i=0;i<menu.numItems;i++){
    var label=String(menu.getItemAt(i,false)).replace(/\u200b/g,"");
    items.push([label.replace(/ /g," \u200b"),String(menu.getItemAt(i,true))]);
  }
  var wasCalculating=d.calculate;
  try{d.calculate=false;menu.setItems(items);menu.value=selected;}
  finally{d.calculate=wasCalculating;}
}
function CDQ_number(s) {
  s=String(s===null||s===undefined?"":s).replace(/[\s\u00a0\u202f]/g,"").replace(",",".");
  if(s==="" || !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(s)) return null;
  var x=Number(s); return isFinite(x)?x:null;
}
function CDQ_fmt(n) { if(n===null||!isFinite(n))return ""; n=Math.round(n*1000)/1000; return String(n===0?0:n).replace(".",","); }
function CDQ_tol(c,e) { return c===null||e===null||c<0||e<=0?null:Math.max(1,Math.ceil(c*.001/e-.5-.0000000001)); }
function CDQ_measureNames() {
  var names=[],phases=["avant","apres"];
  for(var k=0;k<2;k++){
    for(var i=1;i<=6;i++) names.push("charge_point_"+i+"_"+phases[k]+"_correction");
    for(var j=0;j<4;j++) names.push("excentricite_"+phases[k]+"_"+CDQ_positions[j]);
  }
  return names;
}
function CDQ_show(d,n,on) {
  // PDF.js widget updates may reconstruct the live annotation layer and
  // interrupt mobile keyboard input. Only write when the status CHANGES.
  var f=d.getField(CDQ_prefix+n),wanted=on?display.visible:display.hidden;
