function CDQ_status(d,prefix,state) {
  CDQ_show(d,prefix+"_green",state==="green");
  CDQ_show(d,prefix+"_red",state==="red");
  CDQ_show(d,prefix+"_gray",state==="gray");
}
function CDQ_measureStyle(d,n,state,blocked) {
  var f=d.getField(CDQ_prefix+n);if(!f)return;
  // Do not rewrite the same flags or colors on every keystroke. In PDF.js
  // those redundant appearance writes can cause a field to lose a live edit.
  if(!!f.readonly!==!!blocked)f.readonly=!!blocked;
  // CSS and native AP already supply neutral widget colors in the CDQ reader.
  // Keep explicit color setup for standalone PDF/Acrobat only.
  if(app.viewerType!=="PDF.js"){
    f.textColor=CDQ_colors.black;
    f.fillColor=CDQ_colors.white;
    f.strokeColor=CDQ_colors.line;
  }
  CDQ_show(d,"coin_"+n+"_green",state==="green");
  CDQ_show(d,"coin_"+n+"_red",state==="red");
}
function CDQ_validateNumber(ev) {
  var s=String(ev.value===null?"":ev.value);
  if(s.replace(/\s/g,"")==="" || s.replace(/\s/g,"")==="-")return;
  var v=CDQ_number(s),name=ev.targetName||(ev.target?ev.target.name:"");
  if(CDQ_prefix&&name.indexOf(CDQ_prefix)===0)name=name.slice(CDQ_prefix.length);
  var bad=v===null || (name==="echelon"&&v<=0) || ((name==="charge_excentricite"||name.indexOf("charge_utilisee")>=0)&&v<0);
  if(bad){ev.rc=false;try{app.alert(name==="echelon"?"L’échelon doit être un nombre supérieur à zéro.":"Saisir une valeur numérique valide. Exemple : 1000.000 ou 1000,000.");}catch(e){}}
}
