// CDQ V12: six automatic test loads from verified span, without losing edits.
var CDQ_autoLast=[null,null,null,null,null,null];
var CDQ_autoManual=[false,false,false,false,false,false];
function CDQ_autoSpan(s){
  s=String(s===null||s===undefined?'':s).replace(/[\u00a0\u202f]/g,' ').trim();
  // Accept 200, 200 kg or a range ending at 200 kg, but not ambiguous free text.
  if(!s||/[^0-9.,\s+\-/àa\u2013\u2014kKgGtTlLbBoOzZ]/.test(s))return null;
  var matches=s.match(/[+]?(?:\d+(?:[.,]\d*)?|[.,]\d+)/g);
  if(!matches||matches.length<1||matches.length>2)return null;
  var n=Number(matches[matches.length-1].replace(',','.'));
  return isFinite(n)&&n>0?n:null;
}
function CDQ_autoLoads(span,e){
  if(span===null)return null;
  var out=[],six=(Math.abs(span/6-Math.round(span/6))<1e-9),parts=six?[1/6,2/6,3/6,4/6,5/6,1]:[.1,.2,.4,.6,.8,1];
  // The 200 kg scale uses the existing CDQ ten-part sequence, not sixths.
  if(Math.abs(span-200)<1e-9)parts=[.1,.2,.4,.6,.8,1];
  for(var i=0;i<6;i++){
    var n=span*parts[i];
    if(e!==null&&e>0){
      // The last point must equal the verified span; do not guess if not a multiple of e.
      if(i===5&&Math.abs(span/e-Math.round(span/e))>1e-8)return null;
      n=Math.round(n/e)*e;
    }
    n=Math.round(n*1000000000)/1000000000;
    if(!isFinite(n)||n<=0||n>span+1e-8||(i>0&&n<=out[i-1]))return null;
    out.push(n);
  }
