}
function CDQ_autoCharges(d){
  var span=CDQ_autoSpan(CDQ_get(d,'etendue_verifiee'));
  var e=CDQ_number(CDQ_get(d,'echelon'));
  var proposal=CDQ_autoLoads(span,e);
  for(var i=0;i<6;i++){
    var name='charge_point_'+(i+1)+'_charge_utilisee',current=CDQ_get(d,name).trim();
    var prior=CDQ_autoLast[i];
    // A value entered by the technician is authoritative. Blank edit also stays manual.
    if(prior!==null&&current!==prior)CDQ_autoManual[i]=true;
    else if(prior===null&&current!==''&&current!=='-'&&current!=='–'&&current!=='—')CDQ_autoManual[i]=true;
    if(CDQ_autoManual[i])continue;
    if(!proposal){
      if(prior!==null&&current===prior){CDQ_set(d,name,'');CDQ_autoLast[i]=null;}
      continue;
    }
    var value=CDQ_fmt(proposal[i]);
