  var s1=CDQ_get(d,'date_jour').trim(),s2=CDQ_get(d,'date_mois').trim(),s3=CDQ_get(d,'date_annee').trim();
  var freq=CDQ_get(d,'frequence_etalonnage'),months={'1 mois':1,'2 mois':2,'3 mois':3,'4 mois':4,'5 mois':5,'6 mois':6,'12 mois':12,'24 mois':24,'1 an':12,'2 ans':24}[freq];
  var day=Number(s1),month=Number(s2),year=Number(s3),date=new Date(year,month-1,day);
  var valid=/^\d{1,2}$/.test(s1)&&/^\d{1,2}$/.test(s2)&&/^\d{4}$/.test(s3)&&year>=1000&&month>=1&&month<=12&&day>=1&&day<=31&&date.getFullYear()===year&&date.getMonth()===month-1&&date.getDate()===day&&months>0;
  if(!valid)return;
  var total=month-1+months,yy=year+Math.floor(total/12),mm=total%12+1,dd=Math.min(day,new Date(yy,mm,0).getDate());
  var proposed=[String(dd).padStart(2,'0'),String(mm).padStart(2,'0'),String(yy)];
  var names=['prochain_jour','prochain_mois','prochain_annee'];
  var current=names.map(function(n){return CDQ_get(d,n);});
  var previouslyAuto=CDQ_nextAuto&&current.every(function(v,i){return v===CDQ_nextAuto[i];});
  if(current.some(function(v){return v.trim()!=='';})&&!previouslyAuto)return;
  for(var i=0;i<3;i++)CDQ_set(d,names[i],proposed[i]);
