    var problem=JSON.stringify(choices),invalid=facts.count>0,corrected=invalid&&facts.unresolved.length===0;
    var base=invalid?choices[0].replace(/_corrige$/,""):"aucun";
    var menu=d.getField(CDQ_prefix+"probleme_constate");
    if(menu){
