    CDQ_set(d,"dernier_probleme",problem);
    CDQ_set(d,"problemes_nombre",facts.count?facts.count+" problème"+(facts.count>1?"s sélectionnés":" sélectionné"):"Aucun problème constaté");
    CDQ_set(d,"problemes_detail",CDQ_problemDetail(facts));
